-- Disposable PostgreSQL fixture: never run against business data.
create schema private;create schema auth;
create role anon;create role authenticated;
grant usage on schema private,auth,public to authenticated;
create function auth.uid() returns uuid language sql as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table proc_profiles(id uuid primary key,active boolean,role_key text);
insert into proc_profiles values('00000000-0000-4000-8000-000000000001',true,'admin'),('00000000-0000-4000-8000-000000000002',true,'buyer');
create function private.proc_assert_data_admin() returns void language plpgsql security definer as $$begin if not exists(select 1 from public.proc_profiles where id=auth.uid() and active and role_key='admin') then raise exception 'Admin required' using errcode='42501';end if;end$$;
create function private.proc_po_status_guard() returns trigger language plpgsql as $$begin if old.po_no<>new.po_no then raise exception 'immutable';end if;return new;end$$;
create table proc_rfqs(id uuid primary key default gen_random_uuid(),rfq_no text unique,created_at timestamptz default now(),status text);
create table proc_purchase_orders(id uuid primary key default gen_random_uuid(),po_no text unique,created_at timestamptz default now(),status text);
create trigger po_guard before update on proc_purchase_orders for each row execute function private.proc_po_status_guard();
create table proc_requirements(id uuid primary key default gen_random_uuid(),requirement_no text unique,created_at timestamptz default now(),ordered_qty numeric default 0,received_qty numeric default 0);
create table proc_stock_counts(id uuid primary key default gen_random_uuid(),count_no text unique,created_at timestamptz default now());
create table proc_grns(id uuid primary key default gen_random_uuid(),grn_no text unique,created_at timestamptz default now(),po_id uuid references proc_purchase_orders,status text);
create table proc_suppliers(id uuid primary key default gen_random_uuid(),supplier_code text,name text,created_at timestamptz default now());
create table proc_companies(id uuid primary key default gen_random_uuid(),default_supplier_id uuid references proc_suppliers,name text,created_at timestamptz default now());
create table proc_supplier_scopes(id uuid primary key default gen_random_uuid(),supplier_id uuid references proc_suppliers);
create table proc_quotes(id uuid primary key default gen_random_uuid(),rfq_id uuid references proc_rfqs on delete cascade,quote_ref text);
create table proc_rfq_items(id uuid primary key default gen_random_uuid(),rfq_id uuid references proc_rfqs on delete cascade,requirement_id uuid references proc_requirements);
create table proc_quote_lines(id uuid primary key default gen_random_uuid(),quote_id uuid references proc_quotes on delete cascade,rfq_item_id uuid references proc_rfq_items on delete cascade);
create table proc_awards(id uuid primary key default gen_random_uuid(),quote_line_id uuid references proc_quote_lines);
create table proc_po_lines(id uuid primary key default gen_random_uuid(),po_id uuid references proc_purchase_orders on delete cascade,source_quote_line_id uuid references proc_quote_lines,requirement_id uuid references proc_requirements,qty numeric,cancelled_qty numeric default 0);
create table proc_grn_lines(id uuid primary key default gen_random_uuid(),grn_id uuid references proc_grns on delete cascade,po_line_id uuid references proc_po_lines,accepted_qty numeric);
create table proc_supplier_invoices(id uuid primary key default gen_random_uuid(),po_id uuid references proc_purchase_orders,invoice_no text);
create table proc_invoice_lines(id uuid primary key default gen_random_uuid(),invoice_id uuid references proc_supplier_invoices on delete cascade);
create table proc_whatsapp_po_dispatches(id uuid primary key default gen_random_uuid(),po_id uuid references proc_purchase_orders,status text);
create table proc_whatsapp_rfq_dispatches(id uuid primary key default gen_random_uuid(),rfq_id uuid references proc_rfqs,status text);
create table proc_automation_jobs(id uuid primary key default gen_random_uuid(),entity_id uuid);
do $$declare t text;begin foreach t in array array['proc_po_balance_actions','proc_rejection_cases','proc_rfq_suppliers','proc_item_requests','proc_company_price_documents','proc_company_price_list_lines','proc_company_price_lists','proc_company_list_items','proc_stock_count_lines'] loop execute format('create table %I(id uuid primary key default gen_random_uuid())',t);end loop;end$$;
create table proc_audit_logs(table_name text,record_id uuid,action text,new_data jsonb,user_id uuid);
create table proc_stock_balances(qty numeric);insert into proc_stock_balances values(20);
create table proc_stock_ledger(note text);insert into proc_stock_ledger values('original stock history');
create function public.proc_refresh_requirement_status(p uuid) returns void language sql as $$select$$;
create function public.proc_create_rfq_v3() returns jsonb language plpgsql as $$declare rfq_id uuid;rfq_no text:='OBSOLETE';begin insert into public.proc_rfqs(rfq_no) values(rfq_no) returning id into rfq_id;return jsonb_build_object('id',rfq_id,'rfq_no',rfq_no);end$$;
insert into proc_rfqs(rfq_no,created_at) values('OLD-RFQ','2026-01-01'),('001','2026-01-02');
insert into proc_purchase_orders(po_no) values('OLD-PO');

